export class CocoFrameApiError extends Error {
  readonly status: number;
  readonly payload: unknown;
  constructor(status: number, payload: unknown) {
    super(`CocoFrame API request failed with status ${status}`);
    this.name = "CocoFrameApiError";
    this.status = status;
    this.payload = payload;
  }
}

export type GreetPersonInput = { readonly params: { readonly "name": string; }; readonly query: { readonly "excited"?: boolean; }; };
export type GreetPersonOutput = { readonly "message": string; };

export async function greetPerson(baseUrl: string, input: GreetPersonInput, requestOptions: CocoFrameRequestOptions = {}): Promise<GreetPersonOutput> {
  let pathname = "/api/greet/:name";
  for (const [key, value] of Object.entries(input.params)) pathname = pathname.replace(`:${key}`, encodeURIComponent(String(value)));
  const url = new URL(pathname, baseUrl);
  for (const [key, value] of Object.entries(input.query)) {
    if (Array.isArray(value)) value.forEach((item) => url.searchParams.append(key, String(item)));
    else if (value !== undefined) url.searchParams.set(key, String(value));
  }
  const headers = new Headers(requestOptions.headers);
  
  const response = await (requestOptions.fetch ?? globalThis.fetch)(url, {
    method: "GET",
    headers,
    ...(requestOptions.credentials ? { credentials: requestOptions.credentials } : {}),
    
  });
  const payload: unknown = response.headers.get("content-type")?.includes("application/json") ? await response.json() : await response.text();
  if (!response.ok) throw new CocoFrameApiError(response.status, payload);
  return payload as GreetPersonOutput;
}

export type HealthInput = void;
export type HealthOutput = { readonly "ok": true; readonly "framework": string; };

